-- $>B> 28A8B =0 2878B5: A=8<>: 45;0NB =0 ?>ABC ?@8 2K40G5 :0@BK.
UPDATE v
SET v.DocumentFilesID = f.PhotoId
FROM dbo.Visits v
JOIN dbo.Requests r ON r.Id = v.RequestID
JOIN (VALUES
        (1, N'D0C0F11E000000000000000000000001'),
        (2, N'D0C0F11E000000000000000000000002'),
        (3, N'D0C0F11E000000000000000000000003'),
        (4, N'D0C0F11E000000000000000000000004')
     ) AS f(VisitorId, PhotoId) ON f.VisitorId = r.VisitorID;

COMMIT TRANSACTION;

SELECT
    (SELECT COUNT(*) FROM dbo.DocumentFiles)                          AS photos,
    (SELECT COUNT(*) FROM dbo.Visits WHERE DocumentFilesID IS NOT NULL) AS visits_with_photo,
    (SELECT COUNT(*) FROM dbo.Visits)                                 AS visits_total;
